char *big_sum(char *a, char *b) {
  int length_a = strlen(a), length_b = strlen(b);
  int i = 0, over = 0, result_length = 0;
  char *result = malloc((length_a + length_b) * sizeof(char));

  while (i < length_a || i < length_b) {
    int current_a = 0, current_b = 0;
    if (i < length_a) {
      current_a = a[length_a - 1 - i] - '0';
    }
    if (i < length_b) {
      current_b = b[length_b - 1 - i] - '0';
    }
    int current = current_a + current_b + over;
    over = current / 10;
    current = current % 10;
    result[result_length] = current + '0';
    result_length++;
    i++;
  }
  if (over > 0) {
    result[result_length] = over + '0';
    result_length++;
  }
  result[result_length] = '\0';

  return string_reverse(result);
}

char *big_multiply(char *a, char *b) {
  int length_a = strlen(a), length_b = strlen(b);
  int i;
  char *total = "0";
  for (i = 0; i < length_b; i++) {
    // Multiply a with b[length_b - 1 - i]
    int current_b = b[length_b - 1 - i] - '0';
    int j, over = 0, sum_length = 0;
    char *sum = malloc((length_a + 1) * sizeof(char));
    for (j = 0; j < length_a; j++) {
      int current_a = a[length_a - 1 - j] - '0';
      int current = current_a * current_b + over;
      over = current / 10;
      current = current % 10;
      sum[sum_length] = current + '0';
      sum_length++;
    }
    if (over > 0) {
      sum[sum_length] = over + '0';
      sum_length++;
    }
    sum[sum_length] = '\0';
    sum = string_reverse(sum);
    sum = string_append_zero(sum, i);
    total = big_sum(total, sum);
  }
  return total;
}

int big_compare(char *a, char *b) {
  if (strlen(a) == strlen(b)) {
    return strcmp(a, b);
  }
  return (strlen(a) > strlen(b)) ? 1 : -1;
}

char *string_append_zero(char *a, int total) {
  int length_a = strlen(a);
  char *result = malloc((length_a + total) * sizeof(char));
  int i;
  for (i = 0; i < length_a; i++) {
    result[i] = a[i];
  }
  for (; i < length_a + total; i++) {
    result[i] = '0';
  }
  return result;
}

char *string_reverse(char *a) {
  int length = strlen(a);
  int middle = length / 2;
  int i;
  char temp;

  for (i = 0; i < middle; i++) {
    temp = a[i];
    a[i] = a[length - 1 - i];
    a[length - 1 - i] = temp;
  }

  return a;
}

void try(char *left[2], char *right[2], char *targets[2], char *result) {
  while (1) {
    char *sum[2] = {big_sum(left[0], right[0]), big_sum(left[1], right[1])};

    if (fract_compare(sum, targets) == 0) {
      if (big_compare(sum[0], targets[0]) != 0) {
        printf("Impossible\n");
      } else {
        string_compress(result);
      }

      return;
    }

    if (big_compare(sum[0], targets[0]) > 0 || big_compare(sum[1], targets[1]) > 0) {
      printf("Impossible\n");

      return;
    }

    long long length = strlen(result);
    if (fract_compare(sum, targets) > 0) {
      result[length] = 'B';
      result[length + 1] = '\0';
      strcpy(right[0], sum[0]);
      strcpy(right[1], sum[1]);
    } else {
      result[length] = 'A';
      result[length + 1] = '\0';
      strcpy(left[0], sum[0]);
      strcpy(left[1], sum[1]);
    }
    result[length + 1] = '\0';
  }
}

int max(int a, int b) {
