void string_compress(char *string) {
  long long length = strlen(string);
  long long i, current_total = 1;
  char prev = string[0], current;
  for (i = 1; i < length; i++) {
    current = string[i];
    if (current == prev) {
      current_total++;
    } else {
      printf("%llu%c", current_total, prev);
      prev = current;
      current_total = 1;
    }
  }
  printf("%llu%c", current_total, prev);
  printf("\n");
}

